export function lensRay(x, y, ior, depth = 2.5) {
  // Unit sphere, orthographic incident ray; both interfaces obey Snell's law.
  const z2 = 1-x*x-y*y;
  if (z2 <= 0) return null;
  const entry = [x,y,Math.sqrt(z2)], incoming = [0,0,-1];
  const inside = refract(incoming, entry, 1/ior);
